#include "bridge.h"
int fg153_buffers_enabled(void){const char*v=getenv("GGML_GOOSE_BUFFERS");return !v||strcmp(v,"0")!=0;}
int64_t fg153_bg(int64_t p,int64_t k,int64_t i){auto*t=(ggml_tensor*)(intptr_t)p;auto*a=(ggml_tallocr*)(intptr_t)p;switch(k){case 0:return(intptr_t)t->data;case 1:return(intptr_t)t->view_src;case 2:return(intptr_t)t->buffer;case 3:return t->view_offs;case 7:return(intptr_t)t->extra;case 4:return(intptr_t)((ggml_tensor**)(intptr_t)p)[i];case 5:return((int64_t*)(intptr_t)p)[i];case 10:return(intptr_t)a->buffer;case 11:return(intptr_t)a->base;case 12:return a->alignment;case 13:return a->offset;case 20:return sizeof(ggml_tallocr);case 21:return GGML_STATUS_SUCCESS;default:GGML_ABORT("bad Goose buffer field");}}
void fg153_bp(int64_t p,int64_t k,int64_t i,int64_t v){auto*t=(ggml_tensor*)(intptr_t)p;auto*a=(ggml_tallocr*)(intptr_t)p;switch(k){case 0:t->data=(void*)(intptr_t)v;return;case 2:t->buffer=(ggml_backend_buffer_t)(intptr_t)v;return;case 7:t->extra=(void*)(intptr_t)v;return;case 5:((int64_t*)(intptr_t)p)[i]=v;return;case 6:((ggml_tensor**)(intptr_t)p)[i]=(ggml_tensor*)(intptr_t)v;return;case 10:a->buffer=(ggml_backend_buffer_t)(intptr_t)v;return;case 11:a->base=(void*)(intptr_t)v;return;case 12:a->alignment=v;return;case 13:a->offset=v;return;default:GGML_ABORT("bad Goose buffer write");}}
int64_t fg153_bs(int64_t op,int64_t a,int64_t b,int64_t c){auto buffer=(ggml_backend_buffer_t)(intptr_t)a;auto buft=(ggml_backend_buffer_type_t)(intptr_t)a;auto tensor=(ggml_tensor*)(intptr_t)b;switch(op){
case 0:GGML_ABORT("Goose buffer invariant failed");case 1:return(intptr_t)ggml_backend_buffer_get_base(buffer);case 2:return ggml_backend_buffer_get_alignment(buffer);case 3:return ggml_backend_buffer_is_meta(buffer);case 4:return ggml_backend_buffer_get_alloc_size(buffer,tensor);case 5:return ggml_backend_buffer_get_size(buffer);case 6:return ggml_backend_buffer_init_tensor(buffer,tensor);case 7:ggml_backend_buffer_free(buffer);return 0;
case 8:return(intptr_t)calloc(1,(size_t)a);case 9:return ggml_backend_buft_get_alignment(buft);case 10:return ggml_backend_buft_get_max_size(buft);case 11:return ggml_backend_buft_get_alloc_size(buft,tensor);case 12:free((void*)(intptr_t)a);return 0;case 13:return(intptr_t)ggml_backend_buft_alloc_buffer(buft,(size_t)b);case 14:return(intptr_t)ggml_backend_multi_buffer_alloc_buffer((ggml_backend_buffer_t*)(intptr_t)a,(size_t)b);
case 15:return ggml_get_no_alloc((ggml_context*)(intptr_t)a);case 16:return(intptr_t)ggml_get_first_tensor((ggml_context*)(intptr_t)a);case 17:return(intptr_t)ggml_get_next_tensor((ggml_context*)(intptr_t)a,tensor);case 18:return(intptr_t)ggml_backend_buft_alloc_buffer_n(buft,(ggml_tensor**)(intptr_t)b,(int)c);case 19:return ggml_backend_buft_get_alloc_size_n(buft,(ggml_tensor**)(intptr_t)b,(int)c);default:GGML_ABORT("bad Goose buffer primitive");}}
